function evidence = f90_xrobo03_extract_candidate_evidence(modelPath, outDir)
%f90_xrobo03_extract_candidate_evidence Connection-aware Simscape evidence entry.
%   The scenario engine, official inputs, and dynamic metrics are unchanged.
%   COMPATIBILITY binds the GROUP_SCORING structure audit that counts only connected
%   physical-signal measurement channels and traces those channels through
%   PS-Simulink converters to the public outputs.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

taskRoot = fileparts(mfilename("fullpath"));
localRequireFile(fullfile(taskRoot, ...
    "f90_xrobo03_extract_evidence.m"), ...
    "present", ...
    "SimuVerity:F90:XROBO03:ExtractorBinding");
localRequireFile(fullfile(taskRoot, ...
    "f90_xrobo03_static_audit.m"), ...
    "present", ...
    "SimuVerity:F90:XROBO03:StaticAuditBinding");
localRequireFile(fullfile(taskRoot, ...
    "f90_xrobo03_static_audit_policy.json"), ...
    "present", ...
    "SimuVerity:F90:XROBO03:PolicyBinding");

evidence = f90_xrobo03_extract_evidence(modelPath, outDir);
assert(isfield(evidence, "extraction_only") && ...
    logical(evidence.extraction_only), ...
    "SimuVerity:F90:XROBO03:ExtractionContract", ...
    "Candidate evaluator must return extraction-only evidence.");
assert(isfield(evidence, "candidate_evidence_ready") && ...
    logical(evidence.candidate_evidence_ready), ...
    "SimuVerity:F90:XROBO03:EvidenceContract", ...
    "Candidate evaluator did not return the bound GROUP_SCORING evidence semantics.");
assert(isfield(evidence, "static_audit_current_pass") && ...
    logical(evidence.static_audit_current_pass), ...
    "SimuVerity:F90:XROBO03:StaticAudit", ...
    "The connection-aware GROUP_SCORING static audit did not complete.");
evidencePath = fullfile(outDir, "evidence.json");
assert(isfile(evidencePath), "SimuVerity:F90:XROBO03:EvidenceMissing", ...
    "Evidence extractor did not write evidence.json.");
fprintf("F90_XROBO03_current_EVIDENCE_ONLY output=%s\n", evidencePath);
end

function localRequireFile(pathValue, expectedFilePresence, identifier)
assert(isfile(pathValue), identifier, ...
    "A required COMPATIBILITY evaluator dependency is missing: %s", pathValue);
actualFilePresence = xp9_file_presence_file(string(pathValue));
expectedFilePresence = lower(string(expectedFilePresence));
if actualFilePresence ~= expectedFilePresence
    error(identifier, ...
        "COMPATIBILITY evaluator dependency file binding mismatch: path=%s expected=%s actual=%s", ...
        pathValue, expectedFilePresence, actualFilePresence);
end
end
